const SHARE = {"/werkzeuge/teilen/": "/werkzeuge/?geteilt=1", "/en/tools/share/": "/en/tools/?shared=1"};
const SCOPES = ["/werkzeuge/", "/en/tools/", "/vorlagen/", "/en/templates/"];
const HUBS = {"de": "/werkzeuge/", "en": "/en/tools/"};

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CORE);
    await cache.addAll(PRECACHE.map(u => new Request(u, { cache: 'reload' })));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keep = new Set([CORE, VENDOR, PAGES]);
    for (const key of await caches.keys()) if (key.startsWith('wt-') && !keep.has(key)) await caches.delete(key);
    await self.clients.claim();
  })());
});

const isPage = path => SCOPES.some(s => path.startsWith(s)) && !/\.[a-z0-9]+$/i.test(path);

self.addEventListener('fetch', event => {
  const req = event.request;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (req.method === 'POST' && SHARE[url.pathname]) { event.respondWith(receiveShare(req, SHARE[url.pathname])); return; }
  if (req.method !== 'GET') return;
  const path = url.pathname;
  if (req.mode === 'navigate' || isPage(path)) {
    if (isPage(path)) event.respondWith(networkFirst(req, path));
    return;
  }
  if (path.startsWith('/assets/wt/vendor/')) { event.respondWith(cacheFirst(req, VENDOR)); return; }
  if (path.startsWith('/assets/wt/') || PRECACHE.includes(path)) { event.respondWith(cacheFirst(req, CORE)); return; }
});

async function cacheFirst(req, name) {
  const cache = await caches.open(name);
  const hit = await cache.match(req, { ignoreSearch: true });
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok && res.type === 'basic') await cache.put(req, res.clone());
  return res;
}

async function networkFirst(req, path) {
  const cache = await caches.open(PAGES);
  const key = new URL(path, self.location.origin).href; // without ?query (handoff flags)
  try {
    const res = await fetch(req);
    if (res.ok && res.type === 'basic' && (res.headers.get('content-type') || '').includes('text/html')) await cache.put(key, res.clone());
    return res;
  } catch (err) {
    const hit = (await caches.match(key)) || (await caches.match(path.startsWith(HUBS.en) ? HUBS.en : HUBS.de));
    if (hit) return hit;
    throw err;
  }
}

// ---------------------------------------------------------------- warm-up on request of a tool page
// The page asks for itself, its module and vendor files once it is idle, so the tool works offline later.
self.addEventListener('message', event => {
  const data = event.data || {};
  if (data.type !== 'warm' || !Array.isArray(data.urls)) return;
  const port = event.ports && event.ports[0];
  event.waitUntil((async () => {
    let ok = true;
    for (const u of data.urls.slice(0, 300)) {
      let url;
      try { url = new URL(u, self.location.origin); } catch { continue; }
      if (url.origin !== self.location.origin) continue;
      const page = isPage(url.pathname);
      if (!page && !url.pathname.startsWith('/assets/wt/')) continue;
      const cache = await caches.open(page ? PAGES : url.pathname.startsWith('/assets/wt/vendor/') ? VENDOR : CORE);
      if (await cache.match(url.pathname)) continue;
      try {
        const res = await fetch(url.pathname, { cache: 'reload' });
        if (res.ok) await cache.put(url.pathname, res); else ok = false;
      } catch { ok = false; }
    }
    if (port) port.postMessage({ type: 'warmed', ok, version: VERSION });
  })());
});

// ---------------------------------------------------------------- share target
async function receiveShare(req, landing) {
  try {
    const form = await req.formData();
    const files = form.getAll('files').filter(f => f && typeof f === 'object' && typeof f.size === 'number');
    await idbPut({ files: files.map(f => ({ name: f.name || 'datei', type: f.type || '', blob: f })), target: null, from: 'share', ts: Date.now() });
  } catch (err) { /* nothing stored → the hub says that nothing arrived */ }
  return Response.redirect(landing, 303);
}

function idbPut(value) {
  return new Promise((resolve, reject) => {
    const open = indexedDB.open('fale-wt', 1);
    open.onupgradeneeded = () => { if (!open.result.objectStoreNames.contains('handoff')) open.result.createObjectStore('handoff'); };
    open.onerror = () => reject(open.error);
    open.onsuccess = () => {
      const db = open.result;
      const tx = db.transaction('handoff', 'readwrite');
      tx.objectStore('handoff').put(value, 'current');
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    };
  });
}
